import json
p=json.load(open('p2.json'))
XL,mp,mq,kpv,kiv,TP,TQ,TV=p
sub={
 "params":{"XL":XL,"mp":mp,"mq":mq,"kpv":kpv,"kiv":kiv,"TPf":TP,"TQf":TQ,"TVf":TV,"w0":2*3.141592653589793*60.0},
 "defs":{
   "Vcmd":"Vset + mq*(Q0 - Qm)",
   "E":"kpv*(Vcmd - Vm) + xv",
   "dlt":"delta - theta",
 },
 "states":{
   "Pm":{"rhs":"(P - Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q - Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V - Vm)/TVf","init":"V0"},
   "xv":{"rhs":"kiv*(Vcmd - Vm)","init":"sqrt((V0 + XL*Q0/V0)**2 + (XL*P0/V0)**2)"},
   "delta":{"rhs":"w0*mp*(P0 - Pm)","init":"theta0 + atan2(XL*P0/V0, V0 + XL*Q0/V0)"}
 },
 "outputs":{
   "P":"V*E*sin(delta - theta)/XL",
   "Q":"V*(E*cos(delta - theta) - V)/XL"
 }
}
json.dump(sub,open('submission.json','w'),indent=1)
